package com.codepathacademy.curriculum;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="curriculum_classes") public class CurriculumClass {
 @Id @GeneratedValue private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="week_id") private CurriculumWeek week; @Column(nullable=false,unique=true) private String code; @Column(name="class_number") private int classNumber; @Column(name="title_en") private String titleEn; @Column(name="title_ml") private String titleMl; @Column(name="editorial_status") private String editorialStatus; @Column(name="estimated_minutes") private int estimatedMinutes; @Column(name="difficulty") private String difficulty; @Column(name="has_exercise") private boolean hasExercise; @Column(name="has_quiz") private boolean hasQuiz;
 protected CurriculumClass(){} public CurriculumClass(CurriculumWeek w,String code,int n,String en,String ml){week=w;this.code=code;classNumber=n;titleEn=en;titleMl=ml;editorialStatus="OUTLINE";estimatedMinutes=n==5?60:35;difficulty="BEGINNER";hasExercise=true;hasQuiz=n<5;} public UUID getId(){return id;} public String getCode(){return code;} public int getClassNumber(){return classNumber;} public String getTitleEn(){return titleEn;} public String getTitleMl(){return titleMl;} public String getEditorialStatus(){return editorialStatus;} public int getEstimatedMinutes(){return estimatedMinutes;} public String getDifficulty(){return difficulty;} public boolean isHasExercise(){return hasExercise;} public boolean isHasQuiz(){return hasQuiz;} public CurriculumWeek getWeek(){return week;}
}
